function debounce(fn, ms) {
  let t;
  return (...args) => {
    clearTimeout(t);
    t = setTimeout(() => fn(...args), ms);
  };
}

button.onclick = async () => {
  const { openModal } = await import('./modal.js');
  openModal();
};

function memoize(fn) {
  const cache = new Map();
  return (key) => {
    if (cache.has(key)) return cache.get(key);
    const v = fn(key);
    cache.set(key, v);
    return v;
  };
}
